mapper.sql:
WHERE gl.is_approve = 1
AND gl.is_active = 1
AND gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_type_id = 2)
AND gld.type = 'Payment' AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

    AND (
    reference LIKE CONCAT('%', #{filter.searchText}, '%')
    OR gl.note LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND gl.date >= #{filter.dateFrom}


    AND gl.date <= #{filter.dateTo}


    AND gl.is_adj = #{filter.adjustEntry}


    AND gld.company_id = #{filter.companyId}


    AND gld.class_id = #{filter.classId}


    AND gld.customer_id = #{filter.organizationId}


    AND gld.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})
